package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.os.Bundle;import android.provider.Settings;import java.util.*;import java.io.*;import java.util.concurrent.TimeUnit;
public final class DisplaySettingsActivity extends LeoActivity {
    protected void onResume(){super.onResume();show();}
    static int keylightLevel(){try{Class<?> properties=Class.forName("android.os.SystemProperties");String value=(String)properties.getMethod("get",String.class,String.class).invoke(null,"persist.leo.keylight.level","20");return Integer.parseInt(value);}catch(Exception e){return 20;}}
    private void show(){int brightness=Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,128),timeout=Settings.System.getInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,60000);list(L.t("Ecran și taste"),Arrays.asList(L.t("Luminozitate · ")+Math.round(brightness*100f/255)+"%",L.t("Stingere ecran · ")+timeout/1000+L.t(" secunde"),L.t("Iluminare taste · ")+keylightLevel(),L.t("Fundaluri și teme"),L.t("Blocare automată taste"),L.t("Dimensiunea textului Leo")),0,new Choice(){public void pick(int i){if(i==0)options(L.t("Luminozitate"),new String[]{"5%","25%","50%","75%","100%"},new Choice(){public void pick(int at){setBrightness(new int[]{13,64,128,192,255}[at]);show();}});else if(i==1)options(L.t("Stingere ecran"),new String[]{L.t("30 secunde"),L.t("1 minut"),L.t("2 minute"),L.t("5 minute"),L.t("10 minute"),L.t("30 minute")},new Choice(){public void pick(int at){setTimeout(new int[]{30000,60000,120000,300000,600000,1800000}[at]);show();}});else if(i==2)keylight();else if(i==3)startActivity(new Intent(DisplaySettingsActivity.this,WallpaperActivity.class));else if(i==4)startActivity(new Intent(DisplaySettingsActivity.this,KeypadLockSettingsActivity.class));else startActivity(new Intent(DisplaySettingsActivity.this,InputSettingsActivity.class));}},"",null);}
    void setBrightness(int value){if(value<13||value>255)return;try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS_MODE,Settings.System.SCREEN_BRIGHTNESS_MODE_MANUAL);Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_BRIGHTNESS,value);}catch(RuntimeException e){notice(L.t("Luminozitate nesalvată"));}}
    void setTimeout(int value){if(value<30000||value>1800000)return;try{Settings.System.putInt(getContentResolver(),Settings.System.SCREEN_OFF_TIMEOUT,value);}catch(RuntimeException e){notice(L.t("Interval nesalvat"));}}
    private void keylight(){if(!new File("/sys/class/leds/button-backlight").isDirectory()||!new File("/system/bin/leo-su").canExecute()){notice(L.t("Controlul iluminării nu este disponibil"));return;}options(L.t("Iluminare la apăsare · 8 secunde"),new String[]{L.t("Oprită"),L.t("Slabă"),L.t("Normală"),L.t("Puternică")},new Choice(){public void pick(int at){final int value=new int[]{0,8,20,40}[at];worker.execute(new Runnable(){public void run(){final boolean ok=setKeylight(value);ui(new Runnable(){public void run(){notice(ok?L.t("Se aplică la următoarea apăsare a unei taste"):L.t("Iluminarea nu poate fi schimbată"));show();}});}});}});}
    static boolean setKeylight(int value){if(value!=0&&value!=8&&value!=20&&value!=40)return false;Process p=null;try{p=new ProcessBuilder("/system/bin/leo-su","-c","setprop persist.leo.keylight.level "+value).redirectErrorStream(true).start();if(!p.waitFor(3,TimeUnit.SECONDS)){p.destroy();return false;}return p.exitValue()==0&&keylightLevel()==value;}catch(Exception e){return false;}finally{if(p!=null){try{p.getInputStream().close();p.getOutputStream().close();}catch(IOException ignored){}}}}
}
